use herdr_nexus_translator::{registry,placement::Place}; use datom_codec::Budget; use std::{env,fs,io}; use std::io::Write; use shared_translator::{FrameWriting,Signalizable};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut a=env::args().skip(1);let p=a.next().ok_or("REGISTRY_PATH")?;let n=a.next().ok_or("NAME")?;let mut b=Budget{remaining:1_000_000,reader:protos::ReaderBudget{remaining:1_000_000},depth:0,maximum_depth:1024};let r=registry::decode(&fs::read_to_string(p)?,&mut b).map_err(|e| format!("{e:?}"))?;let x=registry::select(&r,&n).map_err(|e| format!("{e:?}"))?;let mut out=io::stdout();out.write_frame(&x.signalize()?,shared_translator::FrameCapacity::default())?;Ok(())}
